// The usage fold's THIRD source: what each scheduled occurrence actually came to.
//
// The slot scheduler used to print that per due task into its own Actions log, and the
// fold counted those lines. That writer retired with the slot scheduler (#974) and the
// queue does not print an equivalent — because it does not need to. Every occurrence
// is a work ITEM, and when it converges it closes wearing an `outcome:*` label. The
// record is better than the log line was (it survives Actions retention, it is
// clickable, and it carries the task on its own title) and it is a different read,
// which is what #994 asked for. This module is that read.
//
// APPEND-ONCE past `queueFoldedThrough`, for the same reason the run listing is
// forward-only: this is a paged REST resource where the capture files are local git.
// It is safe to append rather than recompute because a CLOSED item is settled — the
// outcome label is written at convergence and nothing later moves it — so an item is
// counted on the one fold that first sees it closed and never again.
//
// The boundary is `closed_at`, not `updated_at`: the listing is asked for everything
// touched since the mark (a comment on an old item counts as a touch), and only items
// that closed past the mark are counted. Closing happens in real time, so the mark is
// monotone and the filter is exactly-once.
//
// FAIL-SOFT, like every other source here: an unreadable listing costs the queue rows
// this run and leaves the mark where it was.

// One definition of what a work item is, shared with the queue's own reader — a filed
// `[claudinite-work]` issue OR an adopted marked issue, which keeps the person's title.
import { isQueueItem } from '../../src/items/read.mjs';
import {
  parseWorkItemTitle, parseWorkItemBody, taskIdFromPath, outcomeOf,
  PARK_PREFIX, PARK_KINDS, NEEDS_HUMAN,
} from '../../src/items/work-item.mjs';

const API = process.env.GITHUB_API_URL || 'https://api.github.com';

// How far back the FIRST read looks with no mark yet — the day tier's own width, so
// one fold populates the whole window rather than starting it empty.
export const FIRST_READ_LOOKBACK_DAYS = 30;

export const lookbackFrom = (nowIso, days = FIRST_READ_LOOKBACK_DAYS) =>
  new Date(new Date(nowIso).getTime() - days * 86400000).toISOString();

export function makeReader({ token = process.env.GITHUB_TOKEN, api = API, fetchImpl = fetch } = {}) {
  const headers = {
    accept: 'application/vnd.github+json',
    'x-github-api-version': '2022-11-28',
    'user-agent': 'claudinite-usage-fold',
    ...(token ? { authorization: `Bearer ${token}` } : {}),
  };
  return {
    async json(path) {
      const res = await fetchImpl(`${api}${path}`, { headers });
      if (res.status !== 200) return null;
      try { return await res.json(); } catch { return null; }
    },
  };
}

// The task an item belongs to. A filed item says so in its title; an ADOPTED marked
// issue keeps the person's own title and says so in the machine block its body carries
// — the same two-step the dashboard's own reader makes, so a request-shaped run is not
// silently counted as belonging to no task.
export function taskOf(issue) {
  const fromTitle = parseWorkItemTitle(issue?.title);
  if (fromTitle) return { pack: fromTitle.pack, task: fromTitle.task };
  const fromBody = taskIdFromPath(parseWorkItemBody(issue?.body).taskPath);
  return fromBody ? { pack: fromBody.pack, task: fromBody.task } : null;
}

// --- the parks an item collected -------------------------------------------------
// A park is a label an item WORE, so the only record of one is the label event that
// applied it — the item's final labels say where it ended, never where it stopped on
// the way. So each closed item's event listing is read once, on the fold that first
// sees it closed, under the queue's own watermark.
//
// The kinds are decoded exactly as `parkOf` decodes them for a live item: today's
// single `task:status:needs-human-<kind>`, the two-label era's `task:needs-human-<kind>`
// sub-label, and a kind no engine here knows reading as `failure` — the conservative
// lane, so a park whose word this code predates is never dropped.
// @legacy-tolerance advisory:none retire:#1642
const LEGACY_PARK_RE = /^task:needs-human-(.+)$/;

export function parkKindOf(label) {
  const name = String(label ?? '');
  if (name === NEEDS_HUMAN) return 'failure';
  const kind = name.startsWith(PARK_PREFIX)
    ? name.slice(PARK_PREFIX.length)
    : LEGACY_PARK_RE.exec(name)?.[1] ?? null;
  if (kind === null) return null;
  return PARK_KINDS.includes(kind) ? kind : 'failure';
}

// The park kinds one item collected, DEDUPED: an item bounced between a person and the
// machine twice was parked for that kind once as far as "how often did this task need a
// human" is concerned. `null` — never `[]` — when the listing could not be read, so an
// unknown park count stays distinguishable from a clean run.
export async function readParks({ reader, repo, number }) {
  let events = null;
  try { events = await reader.json(`/repos/${repo}/issues/${number}/events?per_page=100`); } catch { return null; }
  if (!Array.isArray(events)) return null;
  const kinds = new Set();
  for (const event of events) {
    if (event?.event !== 'labeled') continue;
    const kind = parkKindOf(event?.label?.name);
    if (kind) kinds.add(kind);
  }
  return [...kinds];
}

// One closed item → a record, or null when it is not this fold's business.
export function recordFor(issue, since) {
  if (!isQueueItem(issue)) return null;
  const closedAt = issue?.closed_at ?? null;
  if (!closedAt) return null;
  if (since && closedAt <= since) return null;
  const task = taskOf(issue);
  if (!task) return null;
  return {
    date: closedAt.slice(0, 10), closedAt, ...task, outcome: outcomeOf(issue) ?? 'none',
    number: issue?.number ?? null,
    // Filled by the caller from the item's own event listing; `null` until then, and
    // `null` still if that listing could not be read.
    parks: null,
  };
}

// The whole read: `{ records, watermark, error? }`.
export async function readQueueOutcomes({ reader, repo, since, now, maxPages = 5 }) {
  const from = since || lookbackFrom(now);
  const records = [];
  try {
    for (let page = 1; page <= maxPages; page += 1) {
      const path = `/repos/${repo}/issues?state=closed&sort=updated&direction=desc`
        + `&since=${encodeURIComponent(from)}&per_page=100&page=${page}`;
      const batch = await reader.json(path);
      if (!Array.isArray(batch) || batch.length === 0) break;
      for (const issue of batch) {
        if (issue?.pull_request) continue;         // the issues endpoint answers with both
        const rec = recordFor(issue, since);
        if (rec) records.push(rec);
      }
      if (batch.length < 100) break;
    }
  } catch {
    return { records: [], watermark: since, error: 'the closed work items could not be listed' };
  }
  // One listing per item, and only for the items this fold is seeing close for the
  // first time — the watermark above is what bounds the cost. An item whose listing
  // fails keeps `parks: null` and its outcome row regardless.
  for (const rec of records) {
    if (rec.number === null) continue;
    rec.parks = await readParks({ reader, repo, number: rec.number });
  }
  const newest = records.map((r) => r.closedAt).sort().pop() ?? null;
  return { records, watermark: newest ?? since ?? null };
}

// The machine-readable records a task's execution leaves in an Actions log
// (skill-usage-metrics DESIGN §4.2), and the parsers that read them back.
//
// TWO FAMILIES, ONE OF THEM HISTORICAL. `claudinite-task-run` was the SLOT
// scheduler's own line, one per due task per run; the slot scheduler is retired
// (#974) and nothing writes that line any more. The parser stays, and only the
// parser: Actions logs from before the retirement are still inside their retention
// window, and the usage fold still counts them. Nothing new should be taught this
// shape — `claudinite-task-exec` below is the live record.
//
// The counts these produce are exact within the Actions log retention window, and
// that is worth stating next to the capture-derived counts they land beside.

// The five things a slot scheduler run could do with a due task. One name per
// outcome, used verbatim as the counter key in the aggregate, so there is no
// mapping table between "what the run said" and "what the fold counted" to drift.
export const TASK_RUN_OUTCOMES = Object.freeze([
  // A dispatch issue was filed: an agent session ran this task.
  'agent',
  // The task ran with NO agent — an `agent_model: none` task (code-work is the
  // whole task), or an agentful one whose code-work requested no agent phase.
  // Kebab, not the declaration field's `code_work`: this word is a WIRE token,
  // constrained to the line format's `[a-z-]+` charset.
  'code-work',
  // Due, but its precondition said there was nothing to do.
  'skipped',
  // Its code-work failed; the run converged the task to a needs-human issue.
  'failed',
  // Due and past its precondition, but no NEW agent run started: this slot was
  // already dispatched (exactly-once), an earlier dispatch is still open
  // (at-most-one-open), or another task claimed the run exclusively. Work that
  // was wanted and did not happen this run.
  'deferred',
]);

// An empty per-task counter row — every outcome present, zeros included, so a row's
// shape never depends on which outcomes a task happened to hit.
export const emptyTaskRun = () => Object.fromEntries(TASK_RUN_OUTCOMES.map((o) => [o, 0]));

// The line format. `v1` is the shape's version: a reader that meets a `v2` line
// knows it is looking at something it was not written for, instead of silently
// half-parsing it.
export const TASK_RUN_TAG = 'claudinite-task-run';
const VERSION = 'v1';

// Actions stamps every log line with its own timestamp before the command's output,
// so the parse tolerates that prefix — without it, a fetched log reads as having
// printed nothing at all.
const LINE_RE = new RegExp(
  String.raw`^(?:\S+\s+)?${TASK_RUN_TAG} ${VERSION} (\S+)/(\S+) \[(\S+)\] ([a-z-]+)\s*$`,
);

// One line → `{ pack, task, slotId, outcome }`, or null for anything that is not a
// record of this version. Deliberately strict: an unknown outcome word is NOT a
// record, because counting it would mint a counter key nothing ever reads.
// The code phase has been renamed twice, and job logs outlive both renames:
// `preprocess` (pre-2026-08-06) and `prework` (pre-2026-08-18) are the earlier
// words for what is now `code-work`. Runs logged under either still parse, each
// normalized straight to the canonical word.
// Exported because the outcome words are also the usage aggregate's counter KEYS,
// and that file holds rows written under the older words. Its decode renames them
// by this same map, so a rename never silently drops a historical count.
// @legacy-tolerance advisory:none retire:#1642
export const LEGACY_TASK_RUN_OUTCOMES = Object.freeze({ preprocess: 'code-work', prework: 'code-work' });

export function parseTaskRun(line) {
  const m = LINE_RE.exec(line);
  if (!m) return null;
  const [, pack, task, slotId, word] = m;
  const outcome = LEGACY_TASK_RUN_OUTCOMES[word] ?? word;
  if (!TASK_RUN_OUTCOMES.includes(outcome)) return null;
  return { pack, task, slotId, outcome };
}

// Every record in one job log. The log is the whole job's output — this picks its
// own lines out of it and ignores everything else.
export function parseTaskRuns(text) {
  const out = [];
  for (const line of String(text ?? '').split('\n')) {
    const rec = parseTaskRun(line);
    if (rec) out.push(rec);
  }
  return out;
}

// --- executor-side execution records ------------------------------------------
// The historical records above say what the retired slot scheduler DID with a due
// task; these record what an EXECUTOR SESSION did with the work it ran. Printed by executor-side code
// (resolve-dispatch on a terminal verdict, record-exec.mjs at convergence), they
// land in the session transcript, ride to the conversation-logs branch with the
// executor's capture step, and the usage fold counts them deterministically —
// the "task statuses out of the conversation logs" half of the census (owner,
// 2026-08-06). Same single-home rule: renderer and parser sit here together.

export const TASK_EXEC_STATUSES = Object.freeze([
  // The dispatch ran to completion within its ceiling; the issue was closed.
  'success',
  // The run failed (task failure or ceiling violation); the item parked.
  'failed',
  // The dispatch named a task file the repo no longer carries — retired, its pack
  // undeclared, or the item's stored path left behind by a pack rename — and the
  // executor closed the issue as obsolete. Not a failure.
  'task-gone',
  // The dispatch was malformed (bad path shape, unparseable declaration) and was
  // parked without running.
  'invalid',
]);

export const TASK_EXEC_TAG = 'claudinite-task-exec';

// The bracketed field is the OCCURRENCE'S IDENTITY, which is a different thing under
// each dispatch mechanism: a slot id (`d2026-08-06`) where slots decide what runs, and
// the work item's issue number (`#867`) where the queue does. `slotId` keeps its name
// for the fielded records that already carry one; what it must never become is a
// constant, since it is the only join from a record back to the work it describes.
export const renderTaskExec = ({ pack, task, slotId, status }) =>
  `${TASK_EXEC_TAG} ${VERSION} ${pack}/${task} [${slotId ?? 'unknown'}] ${status}`;

const EXEC_LINE_RE = new RegExp(
  String.raw`(?:^|\s)${TASK_EXEC_TAG} ${VERSION} (\S+)/(\S+) \[(\S+)\] ([a-z-]+)\s*$`,
);

export function parseTaskExec(line) {
  const m = EXEC_LINE_RE.exec(line);
  if (!m) return null;
  const [, pack, task, slotId, status] = m;
  if (!TASK_EXEC_STATUSES.includes(status)) return null;
  return { pack, task, slotId, status };
}

export function parseTaskExecs(text) {
  const out = [];
  for (const line of String(text ?? '').split('\n')) {
    const rec = parseTaskExec(line);
    if (rec) out.push(rec);
  }
  return out;
}

