49	export function decodeRow(row, totalsFields, fields = {}) {
50	  const out = { ...decodeCounters(row?.totals, totalsFields) };
51	  for (const [key, value] of Object.entries(row ?? {})) {
52	    if (key === 'totals') continue;
53	    const vocab = fields[key];
54	    out[key] = vocab
55	      ? Object.fromEntries(Object.entries(value ?? {}).map(([k, t]) => [k, decodeCounters(t, vocab)]))
56	      : value;
57	  }
58	  return out;
59	}
