61	// A whole file. Version 1 wrote fully-spelled objects and is returned as itself; every
62	// later version is tuples plus a header. An absent or unparsable file is `null` — the
63	// member is not folding, which is a state the page says out loud rather than a zero.
64	export function decodeUsage(doc) {
65	  if (!doc || typeof doc !== 'object') return null;
66	  const version = Number(doc.version ?? 1);
67	  const fields = doc.fields ?? {};
68	  const rows = (map, totalsFields) => Object.fromEntries(
69	    Object.entries(map ?? {}).map(([k, v]) => [k, version >= 2 ? decodeRow(v, totalsFields, fields) : v]),
70	  );
71	  return {
72	    version,
73	    // When the numbers were last CONFIRMED, which is not when the file last landed: a
74	    // quiet repo folds to the same numbers and opens no PR, so the commit date behind
75	    // this file can be older. A version that predates the stamp answers null, and the
76	    // page says "not stated" rather than guessing the head commit's date.
77	    generated: doc.generated ?? null,
78	    foldedThrough: doc.foldedThrough ?? null,
