100	// --- ladders ------------------------------------------------------------------------
101	
102	const DAY_MS = 86400e3;
103	const HOUR_MS = 3600e3;
104	
105	export const dayKey = (t) => new Date(t).toISOString().slice(0, 10);
106	export const hourKey = (t) => new Date(t).toISOString().slice(0, 13);
