117	
118	// A field off a row, as a number or `null`. The whole unknown-is-not-zero rule in one
119	// function, so no caller has to remember it.
120	const at = (row, field) => (typeof row?.[field] === 'number' ? row[field] : null);
121	
122	// --- what the corpus is doing to the sessions ---------------------------------------
123	
124	// The growth series: what came back out of the checks each day, and what the sessions
125	// spent. Every field is null where the fold had no opinion, and a day with
126	// no row at all is null throughout rather than a zero — a repo that folded nothing for
127	// a week did not have a quiet week, it had an unfolded one.
128	export function growthSeries(usage, { now, days = 30 } = {}) {
129	  const ladder = dayLadder(now, days);
130	  const rows = ladder.map((day) => {
131	    const row = usage?.days?.[day];
132	    if (!row) return { day, missing: true, sessions: null, checkRuns: null, checkFailures: null, findings: null, tokensIn: null, tokensOut: null, tokenSessions: null, commits: null, linesAdded: null, linesRemoved: null, releases: null };
133	    // Both scopes together: "how many times did the checks run today" is one question,
134	    // and splitting it by scope here would put the world sweep's weekly rhythm into a
135	    // daily line that is otherwise the Stop hook's.
136	    const scopes = Object.values(row.checks ?? {});
137	    const sum = (f) => (scopes.length ? scopes.reduce((n, s) => n + (s[f] ?? 0), 0) : null);
138	    const findings = Object.values(row.checkFindings ?? {});
139	    return {
140	      day,
141	      missing: false,
142	      sessions: at(row, 'sessions'),
143	      checkRuns: sum('runs'),
144	      checkFailures: sum('failures'),
145	      findings: findings.length ? findings.reduce((n, f) => n + (f.blocking ?? 0) + (f.advisory ?? 0), 0) : null,
146	      tokensIn: at(row, 'tokensIn'),
147	      tokensOut: at(row, 'tokensOut'),
148	      tokenSessions: at(row, 'tokenSessions'),
149	      commits: at(row, 'commits'),
150	      linesAdded: at(row, 'linesAdded'),
151	      linesRemoved: at(row, 'linesRemoved'),
152	      releases: at(row, 'releases'),
153	    };
154	  });
155	
156	  // Which of the optional series this repo's file actually carries. A page that cannot
157	  // tell "nothing happened" from "nothing recorded it" is the failure mode the whole
158	  // format is shaped against, so the answer is carried explicitly and rendered as a
159	  // stated gap rather than an empty chart.
160	  const has = (field) => rows.some((r) => r[field] !== null);
161	  return {
162	    days: rows,
163	    from: ladder[0],
164	    to: ladder[ladder.length - 1],
165	    folded: rows.some((r) => !r.missing),
166	    carries: {
167	      checks: has('checkRuns'),
168	      tokens: has('tokensIn'),
169	      commits: has('commits'),
170	      releases: has('releases'),
171	    },
172	    totals: {
173	      checkRuns: total(rows, 'checkRuns'),
174	      checkFailures: total(rows, 'checkFailures'),
175	      tokensIn: total(rows, 'tokensIn'),
176	      tokensOut: total(rows, 'tokensOut'),
177	      linesAdded: total(rows, 'linesAdded'),
178	      linesRemoved: total(rows, 'linesRemoved'),
179	      commits: total(rows, 'commits'),
180	      releases: total(rows, 'releases'),
181	    },
