185	// A total over the days that HAD an opinion, or null when none did. Never a sum that
186	// silently treats unknown days as zeroes.
187	function total(rows, field) {
188	  const known = rows.map((r) => r[field]).filter((n) => n !== null);
189	  return known.length ? known.reduce((a, b) => a + b, 0) : null;
190	}
191	
192	// --- what the queue closed ----------------------------------------------------------
193	
194	// Per-day outcome counts, from the file, with TODAY topped up from the live issue page
195	// the caller already fetched. The fold runs hourly and its own read is watermarked, so
196	// the last hour or two of closes is exactly what it has not seen — and that is the part
197	// a person looking at this page cares most about.
198	//
