200	// REPLACES the folded row for any day the live window fully covers rather than adding
201	// to it, because a day the fold has already partly counted would otherwise double.
202	export function queueSeries(usage, { now, days = 14, items = [], liveFrom = null } = {}) {
203	  const ladder = dayLadder(now, days);
204	  const live = {};
205	  for (const item of items) {
206	    const t = ms(item.closedAt);
207	    if (t == null) continue;
208	    const day = dayKey(t);
