210	  }
211	  const liveDay = liveFrom == null ? null : dayKey(liveFrom);
212	
213	  return ladder.map((day) => {
214	    const folded = usage?.days?.[day]?.queue ?? null;
215	    const useLive = liveDay !== null && day >= liveDay;
216	    if (useLive) {
217	      const counts = live[day] ?? {};
218	      return { day, source: 'live', ...outcomeRow(counts) };
219	    }
220	    if (!folded) return { day, source: 'none', done: null, delivered: null, obsolete: null, none: null };
221	    const counts = {};
222	    for (const row of Object.values(folded)) {
223	      for (const [word, n] of Object.entries(row)) counts[word] = (counts[word] ?? 0) + n;
224	    }
225	    return { day, source: 'folded', ...outcomeRow(counts) };
226	  });
227	}
228	
229	const outcomeRow = (counts) => ({
230	  done: counts.done ?? 0,
231	  delivered: counts.delivered ?? 0,
232	  obsolete: counts.obsolete ?? 0,
233	  none: counts.none ?? 0,
234	});
235	
236	// --- what ran, hour by hour ----------------------------------------------------------
237	
238	// The two-day run picture: scheduler runs, executor runs, and the sessions that
239	// actually opened, per UTC hour.
240	//
241	// TWO SOURCES, EACH WHERE IT IS BETTER. The live runs listing the page already fetched
242	// is the freshest and reaches back however far its last few dozen runs go; the folded
243	// hours reach three days but stop at the fold's watermark. So the live list wins for
244	// every hour it fully covers — that is every hour AFTER its oldest run, since the hour
245	// that run landed in is only partly covered — and the file answers the rest.
246	//
247	// The sessions and the per-task detail have no live source at all: nothing in a run
248	// listing says whether an agent ran or what it did. Those come from the file or they
249	// are null, and a row says which.
250	export function hourSeries(usage, { now, hours = 48, runs = [] } = {}) {
251	  const ladder = hourLadder(now, hours);
252	  const liveCounts = {};
253	  let oldest = null;
254	  for (const run of runs) {
255	    const t = ms(run.created_at);
256	    if (t == null) continue;
257	    oldest = oldest === null ? t : Math.min(oldest, t);
258	    const kind = runKind(run);
259	    if (!kind) continue;
260	    const row = (liveCounts[hourKey(t)] ??= { scheduler: 0, executor: 0, failed: 0 });
261	    row[kind] += 1;
262	    if (run.status === 'completed' && failedRun(run)) row.failed += 1;
263	  }
264	  // The oldest run's own hour is only partly in the list, so the live window starts at
265	  // the next one — otherwise a busy hour truncated by the page size would read as a
266	  // quiet one and overwrite a complete folded row with it.
267	  const liveFrom = oldest === null ? null : hourKey(oldest + HOUR_MS);
268	
269	  return ladder.map((hour) => {
270	    const folded = usage?.hours?.[hour] ?? null;
271	    const useLive = liveFrom !== null && hour >= liveFrom;
272	    const counts = useLive
273	      ? (liveCounts[hour] ?? { scheduler: 0, executor: 0, failed: 0 })
274	      : (folded ? { scheduler: folded.scheduler ?? 0, executor: folded.executor ?? 0, failed: folded.failed ?? 0 } : null);
275	    return {
276	      hour,
277	      source: useLive ? 'live' : (folded ? 'folded' : 'none'),
278	      scheduler: counts?.scheduler ?? null,
279	      executor: counts?.executor ?? null,
280	      failed: counts?.failed ?? null,
281	      // Sessions are only ever the fold's answer.
282	      agentic: folded ? (folded.agentic ?? null) : null,
283	      tasks: folded?.taskExec ? taskDetail(folded.taskExec) : [],
284	    };
285	  });
286	}
287	
288	// Which of the two workflows a run belongs to, or null for the repo's own CI. Two
289	// independent signals, either sufficient: the workflow's PATH (what the engine names
290	// the file) and its display name. A run listed from a cache entry written before the
291	// path was projected still classifies, and a member who renamed the display name still
292	// classifies — which is the point of not resting it on one.
293	const SCHEDULER_RE = /claudinite-scheduler\.yml$|^claudinite scheduler$/i;
294	const EXECUTOR_RE = /claudinite-executor\.yml$|^claudinite executor$/i;
295	
296	export function runKind(run) {
297	  const path = String(run?.path ?? '');
298	  const name = String(run?.name ?? '').trim();
299	  if (SCHEDULER_RE.test(path) || SCHEDULER_RE.test(name)) return 'scheduler';
300	  if (EXECUTOR_RE.test(path) || EXECUTOR_RE.test(name)) return 'executor';
301	  return null;
302	}
303	
304	const failedRun = (run) => run.conclusion !== 'success' && run.conclusion !== 'skipped' && run.conclusion !== 'cancelled';
305	
306	// The per-task executions an hour saw, flattened for a hover: `[{ key, statuses }]`,
307	// worst first so a failure is the first thing read.
308	export function taskDetail(taskExec) {
309	  return Object.entries(taskExec ?? {})
310	    .map(([key, row]) => ({
311	      key,
312	      statuses: Object.entries(row).filter(([, n]) => n > 0).map(([s, n]) => ({ status: s, count: n })),
313	      failed: (row.failed ?? 0) + (row.invalid ?? 0),
314	    }))
315	    .filter((t) => t.statuses.length)
316	    .sort((a, b) => b.failed - a.failed || a.key.localeCompare(b.key));
317	}
318

