// The PAST-DATA plane: one file per repo, read once per head sha.
//
// Everything else this page shows is a live read — what is open right now, what ran in
// the last few dozen runs — and live reads are the one thing a browser dashboard
// cannot afford to make deep. Reaching a month back over the API would be a paginated
// crawl per repo, per load, against the viewer's own rate limit.
//
// So the depth comes from a file the repo already folds for itself:
// `.claudinite/local/usage.GENERATED.json`, written hourly by claudinite-growth's
// usage-fold task. It is content at a sha, so it is cached like every other content
// read here — ZERO requests while the default branch has not moved — and one read
// answers every panel that looks further back than the live window.
//
// NOTHING HERE IMPORTS THE FOLD. The two packs are independent, and the file is
// self-describing precisely so a reader never has to: it carries a `fields` header
// naming the vocabulary each of its positional tuples is spelled in, and the decode
// below expands against THAT rather than against any list of its own. A field added or
// retired on the writing side reads correctly here with no change and no coordinated
// release; a version this code has never seen decodes as far as its own header goes.
//
// UNKNOWN IS NOT ZERO, all the way through. The fold leaves no key where a source
// could not answer — a day before a shallow checkout's history begins, a transcript
// shape carrying no token usage — and every series here carries that through as
// `null`. A chart breaks its line over a null; it never draws it at the floor.

import * as gh from './github.mjs';

export const USAGE_PATH = '.claudinite/local/usage.GENERATED.json';

const ms = (t) => (t == null ? null : new Date(t).getTime());

// --- decoding ---------------------------------------------------------------------

// One counter tuple → named counters, against the vocabulary the FILE declared. A
// `null` slot, or one past the end of a short tuple, yields no key: the writer had no
// opinion, and inventing a zero for it is the one thing this format exists to avoid.
export function decodeCounters(tuple, fields) {
  const row = {};
  (fields ?? []).forEach((f, i) => {
    const n = Array.isArray(tuple) ? tuple[i] : undefined;
    if (typeof n === 'number') row[f] = n;
  });
  return row;
}

// One row → named counters plus its sub-maps. Generic over the header: a key the file
// declares a vocabulary for is a counter group and is expanded; anything else (bare
// per-name counts, like the skill loads) passes through as it stands.
export function decodeRow(row, totalsFields, fields = {}) {
  const out = { ...decodeCounters(row?.totals, totalsFields) };
  for (const [key, value] of Object.entries(row ?? {})) {
    if (key === 'totals') continue;
    const vocab = fields[key];
    out[key] = vocab
      ? Object.fromEntries(Object.entries(value ?? {}).map(([k, t]) => [k, decodeCounters(t, vocab)]))
      : value;
  }
  return out;
}

// A whole file. Version 1 wrote fully-spelled objects and is returned as itself; every
// later version is tuples plus a header. An absent or unparsable file is `null` — the
// member is not folding, which is a state the page says out loud rather than a zero.
export function decodeUsage(doc) {
  if (!doc || typeof doc !== 'object') return null;
  const version = Number(doc.version ?? 1);
  const fields = doc.fields ?? {};
  const rows = (map, totalsFields) => Object.fromEntries(
    Object.entries(map ?? {}).map(([k, v]) => [k, version >= 2 ? decodeRow(v, totalsFields, fields) : v]),
  );
  return {
    version,
    // When the numbers were last CONFIRMED, which is not when the file last landed: a
    // quiet repo folds to the same numbers and opens no PR, so the commit date behind
    // this file can be older. A version that predates the stamp answers null, and the
    // page says "not stated" rather than guessing the head commit's date.
    generated: doc.generated ?? null,
    foldedThrough: doc.foldedThrough ?? null,
    hours: rows(doc.hours, fields.hour),
    days: rows(doc.days, fields.day),
    weeks: rows(doc.weeks, fields.week),
  };
}

// Read one repo's aggregate at a sha. A 404 is an ANSWER — this repo does not fold —
// and it is cached as one, so a fleet sweep does not re-ask every member every load.
export async function readUsage(repo, sha, token) {
  try {
    const text = await gh.getTextAtSha(repo, sha, USAGE_PATH, token);
    if (!text) return null;
    return decodeUsage(JSON.parse(text));
  } catch {
    // A read this page declined to make, or one that failed, is not a repo that does
    // not fold. Both answer null here and the caller distinguishes them by whether it
    // asked at all — the panels say "not read", never "nothing happened".
    return null;
  }
}

// --- ladders ------------------------------------------------------------------------

const DAY_MS = 86400e3;
const HOUR_MS = 3600e3;

export const dayKey = (t) => new Date(t).toISOString().slice(0, 10);
export const hourKey = (t) => new Date(t).toISOString().slice(0, 13);

export function dayLadder(now, days) {
  const start = Math.floor(now / DAY_MS) * DAY_MS - (days - 1) * DAY_MS;
  return Array.from({ length: days }, (_, i) => dayKey(start + i * DAY_MS));
}

export function hourLadder(now, hours) {
  const start = Math.floor(now / HOUR_MS) * HOUR_MS - (hours - 1) * HOUR_MS;
  return Array.from({ length: hours }, (_, i) => hourKey(start + i * HOUR_MS));
}

// A field off a row, as a number or `null`. The whole unknown-is-not-zero rule in one
// function, so no caller has to remember it.
const at = (row, field) => (typeof row?.[field] === 'number' ? row[field] : null);

// --- what the corpus is doing to the sessions ---------------------------------------

// The growth series: what came back out of the checks each day, and what the sessions
// spent. Every field is null where the fold had no opinion, and a day with
// no row at all is null throughout rather than a zero — a repo that folded nothing for
// a week did not have a quiet week, it had an unfolded one.
export function growthSeries(usage, { now, days = 30 } = {}) {
  const ladder = dayLadder(now, days);
  const rows = ladder.map((day) => {
    const row = usage?.days?.[day];
    if (!row) return { day, missing: true, sessions: null, checkRuns: null, checkFailures: null, findings: null, tokensIn: null, tokensOut: null, tokenSessions: null, commits: null, linesAdded: null, linesRemoved: null, releases: null };
    // Both scopes together: "how many times did the checks run today" is one question,
    // and splitting it by scope here would put the world sweep's weekly rhythm into a
    // daily line that is otherwise the Stop hook's.
    const scopes = Object.values(row.checks ?? {});
    const sum = (f) => (scopes.length ? scopes.reduce((n, s) => n + (s[f] ?? 0), 0) : null);
    const findings = Object.values(row.checkFindings ?? {});
    return {
      day,
      missing: false,
      sessions: at(row, 'sessions'),
      checkRuns: sum('runs'),
      checkFailures: sum('failures'),
      findings: findings.length ? findings.reduce((n, f) => n + (f.blocking ?? 0) + (f.advisory ?? 0), 0) : null,
      tokensIn: at(row, 'tokensIn'),
      tokensOut: at(row, 'tokensOut'),
      tokenSessions: at(row, 'tokenSessions'),
      commits: at(row, 'commits'),
      linesAdded: at(row, 'linesAdded'),
      linesRemoved: at(row, 'linesRemoved'),
      releases: at(row, 'releases'),
    };
  });

  // Which of the optional series this repo's file actually carries. A page that cannot
  // tell "nothing happened" from "nothing recorded it" is the failure mode the whole
  // format is shaped against, so the answer is carried explicitly and rendered as a
  // stated gap rather than an empty chart.
  const has = (field) => rows.some((r) => r[field] !== null);
  return {
    days: rows,
    from: ladder[0],
    to: ladder[ladder.length - 1],
    folded: rows.some((r) => !r.missing),
    carries: {
      checks: has('checkRuns'),
      tokens: has('tokensIn'),
      commits: has('commits'),
      releases: has('releases'),
    },
    totals: {
      checkRuns: total(rows, 'checkRuns'),
      checkFailures: total(rows, 'checkFailures'),
      tokensIn: total(rows, 'tokensIn'),
      tokensOut: total(rows, 'tokensOut'),
      linesAdded: total(rows, 'linesAdded'),
      linesRemoved: total(rows, 'linesRemoved'),
      commits: total(rows, 'commits'),
      releases: total(rows, 'releases'),
    },
  };
}

// A total over the days that HAD an opinion, or null when none did. Never a sum that
// silently treats unknown days as zeroes.
function total(rows, field) {
  const known = rows.map((r) => r[field]).filter((n) => n !== null);
  return known.length ? known.reduce((a, b) => a + b, 0) : null;
}

// --- what the queue closed ----------------------------------------------------------

// Per-day outcome counts, from the file, with TODAY topped up from the live issue page
// the caller already fetched. The fold runs hourly and its own read is watermarked, so
// the last hour or two of closes is exactly what it has not seen — and that is the part
// a person looking at this page cares most about.
//
// `items` is the live closed-item list, each `{ closedAt, outcome }`; the top-up
// REPLACES the folded row for any day the live window fully covers rather than adding
// to it, because a day the fold has already partly counted would otherwise double.
export function queueSeries(usage, { now, days = 14, items = [], liveFrom = null } = {}) {
  const ladder = dayLadder(now, days);
  const live = {};
  for (const item of items) {
    const t = ms(item.closedAt);
    if (t == null) continue;
    const day = dayKey(t);
    (live[day] ??= {})[item.outcome ?? 'none'] = ((live[day] ?? {})[item.outcome ?? 'none'] ?? 0) + 1;
  }
  const liveDay = liveFrom == null ? null : dayKey(liveFrom);

  return ladder.map((day) => {
    const folded = usage?.days?.[day]?.queue ?? null;
    const useLive = liveDay !== null && day >= liveDay;
    if (useLive) {
      const counts = live[day] ?? {};
      return { day, source: 'live', ...outcomeRow(counts) };
    }
    if (!folded) return { day, source: 'none', done: null, delivered: null, obsolete: null, none: null };
    const counts = {};
    for (const row of Object.values(folded)) {
      for (const [word, n] of Object.entries(row)) counts[word] = (counts[word] ?? 0) + n;
    }
    return { day, source: 'folded', ...outcomeRow(counts) };
  });
}

const outcomeRow = (counts) => ({
  done: counts.done ?? 0,
  delivered: counts.delivered ?? 0,
  obsolete: counts.obsolete ?? 0,
  none: counts.none ?? 0,
});

// --- what ran, hour by hour ----------------------------------------------------------

// The two-day run picture: scheduler runs, executor runs, and the sessions that
// actually opened, per UTC hour.
//
// TWO SOURCES, EACH WHERE IT IS BETTER. The live runs listing the page already fetched
// is the freshest and reaches back however far its last few dozen runs go; the folded
// hours reach three days but stop at the fold's watermark. So the live list wins for
// every hour it fully covers — that is every hour AFTER its oldest run, since the hour
// that run landed in is only partly covered — and the file answers the rest.
//
// The sessions and the per-task detail have no live source at all: nothing in a run
// listing says whether an agent ran or what it did. Those come from the file or they
// are null, and a row says which.
export function hourSeries(usage, { now, hours = 48, runs = [] } = {}) {
  const ladder = hourLadder(now, hours);
  const liveCounts = {};
  let oldest = null;
  for (const run of runs) {
    const t = ms(run.created_at);
    if (t == null) continue;
    oldest = oldest === null ? t : Math.min(oldest, t);
    const kind = runKind(run);
    if (!kind) continue;
    const row = (liveCounts[hourKey(t)] ??= { scheduler: 0, executor: 0, failed: 0 });
    row[kind] += 1;
    if (run.status === 'completed' && failedRun(run)) row.failed += 1;
  }
  // The oldest run's own hour is only partly in the list, so the live window starts at
  // the next one — otherwise a busy hour truncated by the page size would read as a
  // quiet one and overwrite a complete folded row with it.
  const liveFrom = oldest === null ? null : hourKey(oldest + HOUR_MS);

  return ladder.map((hour) => {
    const folded = usage?.hours?.[hour] ?? null;
    const useLive = liveFrom !== null && hour >= liveFrom;
    const counts = useLive
      ? (liveCounts[hour] ?? { scheduler: 0, executor: 0, failed: 0 })
      : (folded ? { scheduler: folded.scheduler ?? 0, executor: folded.executor ?? 0, failed: folded.failed ?? 0 } : null);
    return {
      hour,
      source: useLive ? 'live' : (folded ? 'folded' : 'none'),
      scheduler: counts?.scheduler ?? null,
      executor: counts?.executor ?? null,
      failed: counts?.failed ?? null,
      // Sessions are only ever the fold's answer.
      agentic: folded ? (folded.agentic ?? null) : null,
      tasks: folded?.taskExec ? taskDetail(folded.taskExec) : [],
    };
  });
}

// Which of the two workflows a run belongs to, or null for the repo's own CI. Two
// independent signals, either sufficient: the workflow's PATH (what the engine names
// the file) and its display name. A run listed from a cache entry written before the
// path was projected still classifies, and a member who renamed the display name still
// classifies — which is the point of not resting it on one.
const SCHEDULER_RE = /claudinite-scheduler\.yml$|^claudinite scheduler$/i;
const EXECUTOR_RE = /claudinite-executor\.yml$|^claudinite executor$/i;

export function runKind(run) {
  const path = String(run?.path ?? '');
  const name = String(run?.name ?? '').trim();
  if (SCHEDULER_RE.test(path) || SCHEDULER_RE.test(name)) return 'scheduler';
  if (EXECUTOR_RE.test(path) || EXECUTOR_RE.test(name)) return 'executor';
  return null;
}

const failedRun = (run) => run.conclusion !== 'success' && run.conclusion !== 'skipped' && run.conclusion !== 'cancelled';

// The per-task executions an hour saw, flattened for a hover: `[{ key, statuses }]`,
// worst first so a failure is the first thing read.
export function taskDetail(taskExec) {
  return Object.entries(taskExec ?? {})
    .map(([key, row]) => ({
      key,
      statuses: Object.entries(row).filter(([, n]) => n > 0).map(([s, n]) => ({ status: s, count: n })),
      failed: (row.failed ?? 0) + (row.invalid ?? 0),
    }))
    .filter((t) => t.statuses.length)
    .sort((a, b) => b.failed - a.failed || a.key.localeCompare(b.key));
}

// The ON-DISK SHAPE of `.claudinite/local/usage.GENERATED.json` — the file this task
// writes, and the only thing that reads it back is this task's next run.
//
// It lives here, beside the fold, because the shape is this task's own business.
// Anything else that consumes the file — a fleet sweep in another repo, an ad-hoc
// query — reads it the way any consumer of a published file does: off the `fields`
// header the file carries, with no code from here. That is the point of declaring
// the vocabulary IN the file rather than in a module a reader would have to import.
//
// WHAT THE SHAPE IS. Every counter row is a positional TUPLE whose field order is
// declared once per file, in that header:
//
//     "fields": { "checks": ["runs", "failures", "errors", "blocking", …] },
//     "checks": { "work": [19, 0, 0, 0, 0, 0, 0] }
//
// rather than a fully-spelled object per row. The names that vary — packs, skills,
// rules, tasks — stay LITERAL KEYS, never dictionary ids: adding or removing one has
// to be nothing but key presence, and week rows freeze forever, so an id table that
// renumbered under them would silently rewrite history.
//
// UNKNOWN IS NOT ZERO. A tuple slot is `null` when that row predates the field (a
// week frozen before a counter existed) — decoding drops the key rather than
// inventing a zero, and the fold's accumulators start it from the first day that
// actually carried it. A row that is short simply has no opinion past its last slot.
//
// READING IS VERSION-TOLERANT. `decodeRow` expands against the FILE's declared
// vocabulary, not this module's, so a file written before a field was added or after
// one was retired still decodes to what it meant. Version 1 — the original
// fully-spelled objects — decodes as itself, which is what lets a fold read back the
// weeks it froze under earlier code without any rollout ordering.
//
// THREE TIERS. Hours (a rolling ~72h of scheduler, executor and agent activity), days
// (recomputed while their raw sources live) and weeks (frozen once). They answer
// different questions on different clocks; see the task's README.

import { TASK_RUN_OUTCOMES, TASK_EXEC_STATUSES, LEGACY_TASK_RUN_OUTCOMES } from './run-record.mjs';
import { PARK_KINDS } from './work-item.mjs';

export const USAGE_VERSION = 3;

// The queue's own outcome words — what `outcomeOf`
// (packs/claudinite-tasks/queue/work-item.mjs) decodes a closed work item to, plus `none`
// for one that closed wearing no outcome label at all.
//
// Spelled here rather than imported from the engine, unlike the two task
// vocabularies above it: those symbols are long fielded, while a NEW engine export
// would not be — the engine and this pack land in separate PRs on separate cycles,
// so every member spends a window holding an older engine beside this pack, and a
// pack that fails to load fails the whole mount's self-test. The drift guard is a
// test instead: `fold-usage.test.mjs` drives the real `outcomeOf` over every outcome
// label and fails if this list stops matching what it can return.
export const QUEUE_OUTCOMES = Object.freeze(['done', 'delivered', 'obsolete', 'none']);

// The counter vocabularies, each in the order its tuple spells them. This is the
// single home for those orders: the fold's empty-row builders derive from it, the
// `fields` header is written from it, and appending a field here is the whole change
// (existing rows read short, so they carry `null` for it until they are recomputed).
export const USAGE_FIELDS = Object.freeze({
  // A day row's own scalars. The first five are counted off the capture files and are
  // always present; the rest come from sources that can be absent — see
  // CAPTURE_DAY_FIELDS.
  day: Object.freeze([
    'captures', 'merges', 'sessions', 'userMessages', 'userCommands',
    'tokensIn', 'tokensOut', 'tokenSessions',
    'commits', 'linesAdded', 'linesRemoved', 'releases',
    'humanSeconds', 'agentSeconds',
  ]),
  // A week row's — `days` is how many day rows it absorbed, and `sessionDays` is the
  // sum of the day-level distinct-session counts, which is not a distinct count.
  week: Object.freeze([
    'days', 'captures', 'merges', 'sessionDays', 'userMessages', 'userCommands',
    'tokensIn', 'tokensOut', 'tokenSessions',
    'commits', 'linesAdded', 'linesRemoved', 'releases',
    'humanSeconds', 'agentSeconds',
  ]),
  // An hour row's. `scheduler` and `executor` are workflow runs STARTED in the hour,
  // `agentic` the sessions that captured in it, and `failed` the subset of the two
  // run counts that concluded in failure.
  hour: Object.freeze(['scheduler', 'executor', 'agentic', 'failed']),
  checks: Object.freeze(['runs', 'failures', 'errors', 'blocking', 'advisory', 'ciRuns', 'ciFailures']),
  checkFindings: Object.freeze(['blocking', 'advisory']),
  // Keyed by MODEL ID. The four usage counters are kept apart here where `tokensIn`
  // is their first three summed, so a reader can price a day per model without
  // anything else in the file changing meaning.
  tokensByModel: Object.freeze(['input', 'cacheRead', 'cacheCreate', 'output']),
  // Keyed by PR NUMBER, in hours. Durations rather than percentiles because a
  // percentile does not fold: a week's p50 is not derivable from its days', so the
  // file carries what a reader needs to compute the quantile over whatever window it
  // is showing. A slot whose far end is unknown — a PR that closes no issue, one
  // whose session never captured — is `null`, which is not a zero lead time.
  prs: Object.freeze(['leadHours', 'issueLeadHours', 'sessionToMergeHours']),
  // Keyed by `pack/task`, plus `(none)` for a session a person started and
  // `(unresolved)` for one whose issue names no execution record.
  taskCost: Object.freeze(['sessions', 'tokensIn', 'tokensOut', 'userMessages']),
  // Keyed by `pack/task`. The park kinds are imported rather than re-spelled: they
  // are this pack's own vocabulary, delivered in the same version as this file, and
  // a counter key that drifted from the label a park actually wears would count
  // nothing.
  parks: PARK_KINDS,
  // Owned by the scheduler, imported rather than re-spelled: the counter keys cannot
  // drift from the outcome words the runs actually emit.
  tasks: TASK_RUN_OUTCOMES,
  taskExec: TASK_EXEC_STATUSES,
  queue: QUEUE_OUTCOMES,
});

// The day fields the capture files themselves answer, and therefore the ones a day row
// always carries a real number for — zero included, because "no session typed a command
// that day" is a fact the captures state. Every OTHER day field comes from a source
// that can be absent (a shallow checkout with no history that far back, a releases
// listing that could not be read, a transcript shape carrying no token usage), and an
// absent source must leave NO KEY rather than a zero: `unknown` is a state of its own,
// and a fold that wrote 0 for it would report a busy day as an idle one.
export const CAPTURE_DAY_FIELDS = Object.freeze([
  'captures', 'merges', 'sessions', 'userMessages', 'userCommands',
]);

// The week field each day field folds into. Same name throughout except the two the
// week spells differently, and `days`, which counts rows rather than summing one.
export const WEEK_FROM_DAY = Object.freeze({ sessionDays: 'sessions' });

// The row's sub-maps that carry a counter TUPLE per key — the ones a vocabulary is
// declared for. The sub-maps whose values are bare numbers are BARE_MAPS below.
export const COUNTER_GROUPS = Object.freeze([
  'checks', 'checkFindings', 'tasks', 'taskExec', 'queue', 'tokensByModel', 'prs', 'taskCost', 'parks',
]);

// The row's sub-maps whose values are BARE NUMBERS — no vocabulary, nothing to expand,
// written and read as they stand. Keyed by a name that varies (a skill, a pack), like
// the counter groups beside them.
export const BARE_MAPS = Object.freeze(['skillLoads']);

// The bounds a reader would otherwise have to guess, declared in the file beside
// `fields` for the same reason: a figure computed under a cap means nothing without
// it. `humanSeconds` counts the gap before each human turn, and an overnight gap is
// not the person's time — ten minutes is the bound above which a gap is a break, and
// the cap is what makes the figure a floor rather than a fiction.
export const USAGE_CAPS = Object.freeze({ humanSeconds: 600 });

const sortKeys = (obj) => Object.fromEntries(Object.keys(obj ?? {}).sort().map((k) => [k, obj[k]]));
const nonEmpty = (obj) => obj !== undefined && obj !== null && Object.keys(obj).length > 0;

// The `fields` header for a file this module's code writes.
export const usageFieldsHeader = () => Object.fromEntries(Object.entries(USAGE_FIELDS).map(([k, v]) => [k, [...v]]));

// The `caps` header for a file this module's code writes. A file without one was
// written before the capped fields existed.
export const usageCapsHeader = () => ({ ...USAGE_CAPS });

// One counter row, object → tuple. An absent key becomes `null` (unknown), never 0.
export function encodeCounters(row, fields) {
  return fields.map((f) => (row?.[f] === undefined || row?.[f] === null ? null : row[f]));
}

// …and back. A `null` slot, or a slot past the end of a short tuple, yields NO key —
// the caller's accumulator then starts that field from the first row that has it,
// exactly as it did when the whole group key was missing.
export function decodeCounters(tuple, fields) {
  const row = {};
  fields.forEach((f, i) => {
    const n = Array.isArray(tuple) ? tuple[i] : undefined;
    if (typeof n === 'number') row[f] = n;
  });
  return row;
}

// A whole day/week row, internal (named counters) → on-disk (tuples). `totals` is the
// row's own scalars; the sub-maps follow, and an EMPTY one is omitted entirely rather
// than written as `{}` — zeros are implicit in this file by construction, so an empty
// map carries nothing a reader cannot derive.
export function encodeRow(row, totalsFields) {
  const out = { totals: encodeCounters(row, totalsFields) };
  for (const map of BARE_MAPS) if (nonEmpty(row[map])) out[map] = sortKeys(row[map]);
  for (const group of COUNTER_GROUPS) {
    if (!nonEmpty(row[group])) continue;
    const fields = USAGE_FIELDS[group];
    out[group] = Object.fromEntries(
      Object.keys(row[group]).sort().map((k) => [k, encodeCounters(row[group][k], fields)]),
    );
  }
  return out;
}

// On-disk → internal, against the FILE's own declared vocabulary. `fields` is the
// file's `fields` header (missing keys fall back to this module's, which is what a
// hand-written or truncated header gets). Group maps always come back present, empty
// when the row omitted them, because every consumer folds them key-wise.
export function decodeRow(row, totalsFields, fields = {}) {
  const out = { ...decodeCounters(row?.totals, totalsFields) };
  for (const map of BARE_MAPS) out[map] = { ...(row?.[map] ?? {}) };
  for (const group of COUNTER_GROUPS) {
    const vocab = fields[group] ?? USAGE_FIELDS[group];
    out[group] = Object.fromEntries(
      Object.entries(row?.[group] ?? {}).map(([k, tuple]) => [k, renameLegacyCounters(group, decodeCounters(tuple, vocab))]),
    );
  }
  return out;
}

// A counter key that has been RENAMED is not a retired field: the count it holds is
// still this row's, under a word the vocabulary no longer spells. Expanding against
// the file's own header gets it back under the old name; this puts it under the new
// one, so the next encode carries it instead of dropping it on the floor. Only the
// `tasks` group has renames — the outcome words, which have moved twice.
// @legacy-tolerance advisory:none retire:#1642
function renameLegacyCounters(group, counters) {
  if (group !== 'tasks') return counters;
  const out = {};
  for (const [name, value] of Object.entries(counters)) {
    const canonical = LEGACY_TASK_RUN_OUTCOMES[name] ?? name;
    // Summed, not overwritten: a row can carry both spellings when it was last
    // written across a rename, and both are counts of the same thing.
    out[canonical] = (out[canonical] ?? 0) + (value ?? 0);
  }
  return out;
}

// Is this parsed file already in the tuple shape? Version 1 files — fully-spelled
// counter objects — are read as themselves by both consumers, so the only question a
// reader has to ask is this one.
export const isTupleFormat = (file) => Number(file?.version ?? 1) >= 2;

// The row vocabularies a parsed file declares, defaulted per key. Both readers pass
// the result into `decodeRow`.
export function fieldsOf(file) {
  const declared = file?.fields ?? {};
  return Object.fromEntries(
    Object.keys(USAGE_FIELDS).map((k) => [k, Array.isArray(declared[k]) ? declared[k] : USAGE_FIELDS[k]]),
  );
}

// --- the file as a whole ---------------------------------------------------------
// Three watermarks and three tiers of rows. Both directions live here because the fold
// reads back its OWN prior state every run — the decode is not a compatibility shim,
// it is half of how the task works.

// The key an hour row is filed under: the UTC hour, `YYYY-MM-DDTHH`. Sorts
// chronologically as text, like the day and week keys beside it.
export const hourKey = (iso) => String(iso ?? '').slice(0, 13);

// Named rows → the on-disk file.
export function encodeUsageFile({
  generated = null, foldedThrough = null, runsFoldedThrough = null, queueFoldedThrough = null,
  prsFoldedThrough = null, hours = {}, days = {}, weeks = {},
} = {}) {
  return {
    version: USAGE_VERSION,
    // WHEN THE DATA LAST MOVED, which is not when the file last landed: a quiet repo
    // recomputes to the same numbers and opens no PR, so the commit date can be days
    // older than the last fold that confirmed them. Deliberately excluded from the
    // worker's unchanged-compare for exactly that reason — a stamp that forced a PR
    // every hour would be a stamp nobody could afford.
    generated,
    foldedThrough,
    runsFoldedThrough,
    queueFoldedThrough,
    prsFoldedThrough,
    // The vocabularies this file's tuples are spelled in, written per file so a reader
    // never has to guess which code wrote it.
    fields: usageFieldsHeader(),
    caps: usageCapsHeader(),
    hours: Object.fromEntries(Object.entries(hours).map(([k, v]) => [k, encodeRow(v, USAGE_FIELDS.hour)])),
    days: Object.fromEntries(Object.entries(days).map(([k, v]) => [k, encodeRow(v, USAGE_FIELDS.day)])),
    weeks: Object.fromEntries(Object.entries(weeks).map(([k, v]) => [k, encodeRow(v, USAGE_FIELDS.week)])),
  };
}

// The file's text: ONE LINE PER ROW. `JSON.stringify(file, null, 2)` would put every
// number on its own line, which for tuple rows is nine lines to carry seven numbers
// and a diff that reads per-number instead of per-day. The row is the unit anyone
// reads and the unit the fold rewrites, so it is the unit a line holds.
export function renderUsageFile(file) {
  const rows = (obj) => Object.entries(obj ?? {})
    .map(([k, v]) => `    ${JSON.stringify(k)}: ${JSON.stringify(v)}`).join(',\n');
  const block = (name, obj, end) => (Object.keys(obj ?? {}).length === 0
    ? [`  ${JSON.stringify(name)}: {}${end}`]
    : [`  ${JSON.stringify(name)}: {`, rows(obj), `  }${end}`]);
  return [
    '{',
    `  "version": ${JSON.stringify(file.version)},`,
    `  "generated": ${JSON.stringify(file.generated ?? null)},`,
    `  "foldedThrough": ${JSON.stringify(file.foldedThrough ?? null)},`,
    `  "runsFoldedThrough": ${JSON.stringify(file.runsFoldedThrough ?? null)},`,
    `  "queueFoldedThrough": ${JSON.stringify(file.queueFoldedThrough ?? null)},`,
    `  "prsFoldedThrough": ${JSON.stringify(file.prsFoldedThrough ?? null)},`,
    ...block('fields', file.fields, ','),
    ...block('caps', file.caps, ','),
    ...block('hours', file.hours, ','),
    ...block('days', file.days, ','),
    ...block('weeks', file.weeks, ''),
    '}',
    '',
  ].join('\n');
}

// The one line the unchanged-compare ignores. The stamp moves every run by
// construction, so comparing the rendered text as-is would open a PR an hour on a
// repo where nothing happened — the exact noise the byte-identical check exists to
// prevent. Named here, beside the writer, so the two cannot disagree about which line
// it is.
export const withoutStamp = (text) => String(text ?? '')
  .split('\n').filter((l) => !/^\s*"generated":/.test(l)).join('\n');

// …and back. A version-1 file is already in the named shape and passes through, which
// is what lets a fold read back weeks it froze before this format existed and lets the
// fleet sweep lead its members' upgrades.
export function decodeUsageFile(file) {
  const empty = {
    generated: null, foldedThrough: null, runsFoldedThrough: null, queueFoldedThrough: null,
    prsFoldedThrough: null, hours: {}, days: {}, weeks: {},
  };
  if (!file || typeof file !== 'object') return empty;
  const marks = {
    generated: file.generated ?? null,
    foldedThrough: file.foldedThrough ?? null,
    runsFoldedThrough: file.runsFoldedThrough ?? null,
    // A file written before the queue read existed carries no mark, which reads as
    // "never folded" — the first fold under this code then starts the series from its
    // own lookback rather than claiming to have covered history it never read.
    queueFoldedThrough: file.queueFoldedThrough ?? null,
    // Likewise for the merged-PR read, which arrived later still.
    prsFoldedThrough: file.prsFoldedThrough ?? null,
  };
  if (!isTupleFormat(file)) {
    return { ...marks, hours: {}, days: file.days ?? {}, weeks: file.weeks ?? {} };
  }
  const fields = fieldsOf(file);
  const rows = (map, totals) => Object.fromEntries(
    Object.entries(map ?? {}).map(([k, v]) => [k, decodeRow(v, totals, fields)]),
  );
  return {
    ...marks,
    // A version-2 file has no hours at all; the tier starts empty and fills from the
    // first fold that reads a run listing.
    hours: rows(file.hours, fields.hour),
    days: rows(file.days, fields.day),
    weeks: rows(file.weeks, fields.week),
  };
}

