// --- CLI ----------------------------------------------------------------------

export async function runExecutorJob() {
  // THE OPERATOR HOLD, FIRST ACT (PRINCIPLES.md) — before the config load, before the
  // first API call, so a held queue reads nothing and writes nothing rather than
  // deriving the world and then declining to act on it.
  if (isSuspended()) { console.log('## Claudinite executor\n'); console.log(suspendedNotice()); return; }
  const { makeGh } = await import('../world/github.mjs');
  const { actionRepoContext, actionsEnv, executorId, repoRoot, runUrlFor } = await import('../world/actions.mjs');
  const { discoverTasks } = await import('../contract/discover.mjs');
  const { loadConfig } = await import('../../../../engine/checks/helpers/repo-context.mjs');
  const { isDormant, dormancyErrors } = await import('../contract/dormancy.mjs');
  const { ensureLabels } = await import('../world/github.mjs');
  const { collectSignalsForTask } = await import('../signals/for-task.mjs');
  const { codeWorkRunner } = await import('./code-work-run.mjs');
  const { agentInvoker } = await import('../world/sessions.mjs');

  const root = repoRoot();
  const { repo, defaultBranch } = actionRepoContext();
  if (!repo) { console.error('GITHUB_REPOSITORY not set — not in an Actions context'); process.exit(1); }
  const config = loadConfig(root);

  console.log('## Claudinite executor\n');
  for (const e of dormancyErrors(config)) console.log(`! ${e.what} — ${e.fix}`);
  if (isDormant(config)) {
    console.log('- this project declares its scheduler dormant — nothing is picked up');
    return;
  }

  const gh = makeGh();
  const { tasks, errors } = await discoverTasks(root, config);
  for (const e of errors) console.log(`! ${e.what}`);
  await ensureLabels(gh, repo, QUEUE_LABELS);

  const runUrl = actionsEnv().GITHUB_RUN_ID
    ? `${actionsEnv().GITHUB_SERVER_URL ?? 'https://github.com'}/${repo}/actions/runs/${actionsEnv().GITHUB_RUN_ID}`
    : null;

  const done = await runExecutor({
    gh, repo, root, config, tasks,
    executorId: actionsEnv().CLAUDINITE_EXECUTOR_ID || `actions-${actionsEnv().GITHUB_RUN_ID ?? 'local'}`,
    runUrl,
    collectSignalsFor: collectSignalsForTask({ gh, repo, root, config, defaultBranch }),
    runTaskCodeWork: codeWorkRunner({ root, repo, defaultBranch }),
    invokeAgent: agentInvoker({ repo, config }),
    heldNow: liveSuspendReader(gh, repo, { log: console.log }),
  });

  console.log(done.length
    ? done.map((d) => `- #${d.issue}: ${d.outcome}`).join('\n')
    : '- nothing ready to pick up');
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  runExecutorJob().catch((e) => { console.error(e); process.exit(1); });
}

