251	async function executeItem({
252	  api, gh, repo, root, config, schedule, byId, pathTo = () => null, item, executorId, claim,
253	  now, heartbeatMs, collectSignalsFor, runTaskCodeWork, invokeAgent, log, resolveTargetOf,
254	}) {
255	  const parsed = parseWorkItemTitle(item.title);
256	  const { taskPath } = parseWorkItemBody(item.body);
257	  // A marked issue's identity is its machine block, not its title (PRINCIPLES.md): the id
258	  // is whichever task owns the worker path the block names.
259	  const id = parsed ? `${parsed.pack}/${parsed.task}` : pathTo(taskPath);
260	  const task = id ? byId.get(id) : null;
261	  // The exec record joins back to the work by pack and task, which a marked issue's
262	  // human title cannot supply — so the resolved id travels with the item.
263	  item.taskId = id;
264	
265	  // --- validate in code, before anything trusts the issue ------------------
266	  if (!taskPath || (!parsed && !id)) {
267	    await converge(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, NEEDS_HUMAN_FAILURE, claim,
268	      'This work item is malformed — its title or first body line does not name a task. Possible forgery; a human should look at it.', 'invalid');
269	    return 'needs-human';
270	  }
271	  if (!task) {
272	    await close(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, TASK_OBSOLETE, 'not_planned',
273	      `\`${id}\` is not a task this repo carries at HEAD (the pack may be undeclared, or the task removed). Closing obsolete.`, 'task-gone');
274	    return 'obsolete';
275	  }
276	  // THE SAME FACT, LEARNED LATER. The task set was built once, at the start of the
277	  // run; one run drains several items from one checkout, and an earlier item's own
278	  // work rewrites that checkout — the mount update deletes a retired task's
279	  // directory out from under the items behind it. So a task can resolve here and
280	  // not exist on disk — the same fact the branch above closes on, and it converges
281	  // the same way. Without this the run reaches code-work and spawns with a cwd that is gone
282	  // (missingbulb/Shepherd#300).
283	  if (!existsSync(task.taskDir)) {
284	    await close(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, TASK_OBSOLETE, 'not_planned',
285	      `\`${id}\` no longer exists in this checkout (\`${task.taskPath}\`) — it was removed while this run was in flight. Nothing ran. Closing obsolete.`, 'task-gone');
286	    return 'obsolete';
287	  }
288	  if (task.taskPath !== taskPath) {
289	    // A MISMATCH HAS TWO CAUSES AND ONLY ONE IS A PERSON'S PROBLEM (#1461). The guard
290	    // exists for a tampered or forged item, whose path names some OTHER task — that
291	    // parks. But an item open across a pack rename hits it too: only the title's id is
292	    // canonicalized (`parseWorkItemTitle`), so the body keeps naming the pre-rename
293	    // directory forever, and parking it strands the item AND holds the task's lane,
294	    // since nothing rewrites an item body. When the path resolves to this very task —
295	    // `taskIdFromPath` canonicalizes too — the item is merely stale, which is the
296	    // `!task` branch's verdict: close it obsolete and let the generator file a fresh
297	    // occurrence at today's path.
298	    const named = taskIdFromPath(taskPath);
299	    if (named && `${named.pack}/${named.task}` === id) {
300	      await close(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, TASK_OBSOLETE, 'not_planned',
301	        `This item names \`${id}\` at \`${taskPath}\`, where it no longer lives — the pack was renamed since the item `
302	        + `was filed, and the task is at \`${task.taskPath}\` now. An item's stored path is never rewritten, so this one `
303	        + 'can never run. Closing obsolete; the scheduler files a fresh occurrence at the current path.', 'task-gone');
304	      return 'obsolete';
305	    }
306	    await converge(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, NEEDS_HUMAN_FAILURE, claim,
307	      `This item's task path (\`${taskPath}\`) is not where \`${id}\` lives at HEAD (\`${task.taskPath}\`). Not running it.`, 'invalid');
308	    return 'needs-human';
309	  }
310	
311	  // --- the single precondition evaluation (PRINCIPLES.md) --------------------
312	  const at = now();
313	  // The item's own facts — its fields, its number, whether somebody woke it — are
314	  // what the terms judge over: a request item's verdict is about the issue it
