141	  const title = lines.findIndex((l) => l.startsWith('# '));
142	  const at = title === -1 ? 0 : title + 1;
143	  lines.splice(at, 0, ...(at === 0 ? [RULES_INDEX_IMPORT, ''] : ['', RULES_INDEX_IMPORT]));
