145	  return true;
146	}
147	
148	// --- the mount's own git attributes -----------------------------------------
149	
150	// Everything Claudinite asks git to know about is a file INSIDE the mount root, so
151	// the attributes file lives there and a member's root `.gitattributes` stays the
152	// repo's own: git reads a `.gitattributes` in any directory, and its patterns are
153	// relative to that directory. Claudinite-owned, so it is converged to exact content
154	// rather than appended to.
155	export const MOUNT_ATTRIBUTES_FILE = `${MOUNT_ROOT}/.gitattributes`;
156	
157	// `*GENERATED*` covers every generated file the mount carries — the rules and skills
158	// indexes, the usage fold — under the canon's GENERATED-file discipline and the
159	// `generated-merge-driver` check that enforces it, so a conflicting merge auto-resolves
160	// and this file never grows a line per artifact.
161	//
162	// The shared subtree is canon-owned content the member never authored, so the git HOST
163	// is told so: Linguist keeps a member's language stats off the corpus (which outweighs
164	// a small member's own source by byte count) and collapses the mount in a converge
165	// diff. Presentation only — the CHECK-scope exclusion is a separate, structural rule
166	// in the file-set builder (engine/checks/helpers/repo-context.mjs), which drops the
167	// mount prefix before attributes are ever consulted, so that exclusion holds on a host
168	// and a checkout that honor no attributes at all.
169	const MOUNT_ATTRIBUTES_TEXT = [
170	  '# GENERATED by Claudinite (engine/converge-wiring.mjs) — the attributes of the',
171	  "# mount's own files. A repo's root .gitattributes is the repo's own.",
172	  '*GENERATED* merge=ours',
173	  `${SHARED_NAME}/** linguist-vendored`,
174	].join('\n') + '\n';
175	
176	// Returns true when the file was written (absent, or drifted from the target).
177	export function ensureMountAttributes(root) {
178	  const path = join(root, MOUNT_ATTRIBUTES_FILE);
179	  if (existsSync(path) && readFileSync(path, 'utf8') === MOUNT_ATTRIBUTES_TEXT) return false;
180	  mkdirSync(dirname(path), { recursive: true });
181	  writeFileSync(path, MOUNT_ATTRIBUTES_TEXT);
182	  return true;
183	}
184	
185	// The three names the wiring used to expose, one per line it appended to the member's
186	// root file. Kept, and pointed at the file that now carries all three, because a
187	// member spends a window holding a NEWER engine beside an OLDER pack: a vendored
188	// pack-update flow still imports the first of these by name, and a removed export is
189	// a link-time SyntaxError that faults the whole flow.
190	/** @deprecated call ensureMountAttributes — the three lines are one converged file. */
191	export const ensureRulesIndexMergeAttribute = ensureMountAttributes;
192	/** @deprecated call ensureMountAttributes. */
193	export const ensureSkillsIndexMergeAttribute = ensureMountAttributes;
194	/** @deprecated call ensureMountAttributes. */
195	export const ensureMountVendoredAttribute = ensureMountAttributes;
196	
197	// What those three appended, plus the `merge=ours` line the tasks pack seeded for the
198	// usage fold — the whole set Claudinite ever planted in a member's ROOT file, taken
199	// back now that the mount has its own (#1748). Each is matched as a whole line, so a
200	// repo's own entry for one of these paths (spelled differently, or carrying other
201	// attributes) is left alone; a root file with nothing but these in it goes away,
202	// leaving a repo that never had one as it was.
203	const RETIRED_ROOT_ATTRIBUTES = [
204	  'claudinite-rules.GENERATED.md merge=ours',
205	  'claudinite-skills.GENERATED.md merge=ours',
206	  'usage.GENERATED.json merge=ours',
207	  `${SHARED_SUBDIR.split(sep).join('/')}/** linguist-vendored`,
208	];
209	
210	export function removeRetiredRootAttributes(root) {
211	  const path = join(root, '.gitattributes');
212	  if (!existsSync(path)) return false;
213	  const text = readFileSync(path, 'utf8');
214	  const kept = text.split('\n').filter((line) => !RETIRED_ROOT_ATTRIBUTES.includes(line.trim()));
215	  const next = kept.join('\n');
216	  if (next === text) return false;
217	  if (next.trim() === '') rmSync(path);
218	  else writeFileSync(path, next);
219	  return true;

