787	// --- the hour tier ----------------------------------------------------------------
788	
789	// How long an hour row lives. Three days: long enough for the two-day view the
790	// dashboard draws plus a fold outage, short enough that the tier stays a few dozen
791	// rows rather than a log.
792	export const HOUR_WINDOW_HOURS = 72;
793	
794	export const withinHourWindow = (key, nowIso, hours = HOUR_WINDOW_HOURS) => {
795	  const age = (new Date(`${String(nowIso).slice(0, 13)}:00:00Z`) - new Date(`${key}:00:00Z`)) / 3600000;
796	  return Number.isFinite(age) && age >= 0 && age < hours;
797	};
798	
799	// The hour rows for this run. Two sources meeting in one row, and they are kept in
800	// separate FIELDS rather than merged, because they are trued up on different clocks:
801	//
802	//   - the run counts (`scheduler`, `executor`, `failed`) are APPENDED from the runs
803	//     read past the watermark, so prior rows carry forward and are added to;
804	//   - the capture-derived counts (`agentic`, and the per-task executions behind the
805	//     hover) are RECOMPUTED from the capture files every run, so they overwrite.
806	//
807	// Merging them into one counter would make the second source's recompute silently
808	// double the first's appended total.
809	export function foldHours({ prior = {}, runs = [], captureHours = {}, now }) {
810	  const hours = {};
811	  for (const [key, row] of Object.entries(prior)) {
812	    if (!withinHourWindow(key, now)) continue;
813	    hours[key] = { ...emptyHour(), ...structuredClone(row), taskExec: {} };
814	  }
815	  for (const run of runs) {
816	    const key = hourKey(run.startedAt);
817	    if (!withinHourWindow(key, now)) continue;
818	    const row = (hours[key] ??= emptyHour());
819	    if (run.workflow === 'scheduler') row.scheduler += 1;
820	    else if (run.workflow === 'executor') row.executor += 1;
821	    if (run.conclusion === 'failure' || run.conclusion === 'timed_out' || run.conclusion === 'startup_failure') {
822	      row.failed += 1;
823	    }
824	  }
825	  for (const [key, capture] of Object.entries(captureHours)) {
826	    if (!withinHourWindow(key, now)) continue;
827	    const row = (hours[key] ??= emptyHour());
828	    row.agentic = capture.agentic;
829	    row.taskExec = structuredClone(capture.taskExec ?? {});
830	  }
831	  return hours;
832	}
833	
834	// The capture files' own view of an hour: how many distinct sessions captured in it,
835	// and what they executed. The filename stamp is the clock — the same stamp the logs
836	// branch's retention rules read, machine-written by the capture step.
837	export function captureHours(files) {
838	  const out = {};
839	  const sessions = {};
840	  for (const file of files) {
841	    if (!file.stamp) continue;
842	    const key = hourKey(file.stamp);
843	    const row = (out[key] ??= { agentic: 0, taskExec: {} });
844	    (sessions[key] ??= new Set()).add(file.sessionId);
845	    addCounters(row.taskExec, file.counts.taskExec);
846	  }
847	  for (const [key, set] of Object.entries(sessions)) out[key].agentic = set.size;
848	  return out;
849	}
850	
851	// --- task invocations -----------------------------------------------------------
852	
853	// How long a task row stays in the DAY tier. Independent of the capture retention
854	// on purpose: these rows come from the scheduler's Actions logs, not from the logs
855	// branch, so nothing about them ages out when a capture file does — and a repo that
856	// captured nothing for a week must still show that its scheduled tasks ran. Past
857	// this, the day row goes and its week row carries it, exactly as the capture-derived
858	// days do.
859	export const TASK_DAY_WINDOW_DAYS = 14;
860	
861	// How long a day row lives at all. Wider than the task rows and wider than the capture
862	// retention, because the local-git and queue series reach further back than either and
863	// the growth panels read a month of them. A day past this drops out of the tier; its
864	// week row keeps what it held.
865	export const DAY_WINDOW_DAYS = 30;
866	
867	export function withinTaskWindow(date, today, days = TASK_DAY_WINDOW_DAYS) {
868	  const age = (new Date(`${today}T00:00:00Z`) - new Date(`${date}T00:00:00Z`)) / 86400000;
869	  return Number.isFinite(age) && age >= 0 && age < days;
870	}
871	
872	// Carry the slot scheduler's task-invocation rows forward while they are still inside
873	// the day window.
874	//
875	// HISTORY ONLY, WITH NO WRITER LEFT. These rows counted what the retired slot
876	// scheduler printed into its own Actions log about each due task; that writer is gone
877	// (#974) and its logs have aged out of retention, so nothing appends to them any more
878	// and the reader that did was retired with them rather than left to spend two API
879	// calls a run finding nothing. What each occurrence came to is read from the queue's
880	// own closed items now (`foldQueueOutcomes`), which is the record that replaced it.
881	//
882	// So this only ages them out: a day row keeps its `tasks` counts until it leaves the
883	// window, and the week rows that already froze them keep them forever.
884	export function carryTaskRuns(days, priorDays = {}, today) {
885	  for (const [date, row] of Object.entries(priorDays)) {
886	    const tasks = row?.tasks;
887	    if (!tasks || !Object.keys(tasks).length || !withinTaskWindow(date, today)) continue;
888	    (days[date] ??= emptyDay()).tasks = structuredClone(tasks);
889	  }
890	  return days;
891	}
892	
893	// --- week buckets --------------------------------------------------------------
894	
895	// The ISO-8601 week a UTC date falls in, `YYYY-Www`. ISO weeks start Monday and
896	// belong to the year containing their Thursday — computed, never approximated,
897	// because an off-by-one here would silently mis-file a whole week's row.
898	export function isoWeek(date) {
899	  const d = new Date(`${date}T00:00:00Z`);
900	  const day = (d.getUTCDay() + 6) % 7;                 // Mon=0 … Sun=6
901	  d.setUTCDate(d.getUTCDate() - day + 3);              // the week's Thursday
902	  const year = d.getUTCFullYear();
903	  const firstThursday = new Date(Date.UTC(year, 0, 4));
904	  const offset = (firstThursday.getUTCDay() + 6) % 7;
905	  firstThursday.setUTCDate(firstThursday.getUTCDate() - offset + 3);
906	  const week = 1 + Math.round((d - firstThursday) / (7 * 86400000));
907	  return `${year}-W${String(week).padStart(2, '0')}`;
908	}
909	
910	// The days to fold into weeks this run: every completed day strictly after the
911	// watermark and strictly before today, in order. Days close strictly in order, so a
912	// single monotone watermark is the WHOLE exactly-once mechanism — no ingest ledger.
913	// `today` is excluded because its capture files are still arriving.
914	export function daysToFold(days, foldedThrough, today) {
915	  return Object.keys(days)
916	    .filter((d) => d < today && (!foldedThrough || d > foldedThrough))
917	    .sort();
918	}
919	
920	// Add one day row into its week row, append-once. Weeks carry `days` — how many day
921	// rows they absorbed — so a fold outage longer than the raw retention window
922	// declares its own hole (`days: 5`) instead of silently under-reporting.
923	//
924	// `sessionDays` rather than `sessions`: every counter here sums exactly under
925	// folding EXCEPT a distinct-session count (a session spanning two days is distinct
926	// in each), so the week-level field is named for what it actually is — the sum of
927	// the day-level distinct counts — rather than claiming a precision folding cannot
928	// give.
929	// Every scalar add is `?? 0` on the WEEK side for the same reason the counter maps
930	// below default rather than crash: a week frozen before a field existed carries no key
931	// for it, and the field must start accumulating from the first day that has it instead
932	// of wedging the watermark or reading back as NaN.
933	export function addDayToWeek(week, day) {
934	  const w = week ?? { skillLoads: {}, checks: {}, checkFindings: {} };
935	  const add = (field, n) => { w[field] = (w[field] ?? 0) + n; };
936	  add('days', 1);
937	  // Every other week scalar is the sum of the day field of the same name — the two
938	  // exceptions are spelled once, in WEEK_FROM_DAY. Driven off the vocabulary rather
939	  // than a hand-written list so a field appended to both rows folds without a third
940	  // edit here, which is where a new counter would otherwise be silently dropped.
941	  //
942	  // A day with NO opinion on a field adds nothing rather than zero: a week that
