525	// Hand off to an agent session (PRINCIPLES.md). ONE call per item, ever — which is
526	// what lets this be as short as it is. The nonce goes on the item before the call
527	// and travels in the payload, so the session can prove the fire it arrived on is
528	// the hand-off this item recorded and stop if it is not.
529	async function handOff({ api, gh, repo, item, task, id, context, result, target = null, executorId, claim, invokeAgent, config, log }) {
530	  const nonce = `${item.number}-${Math.random().toString(36).slice(2, 10)}`;
531	  // Every section lands in the machine's half of the body — the whole body for a
532	  // filed item, the machine block for a marked issue, whose prose is the person's.
533	  const body = editItemBody(item.body, (machine) => {
534	    let out = machine;
535	    // The target's fields first, under the task path: the branch the session
536	    // pushes to, the pull request it amends, the ones its converge supersedes.
537	    if (target) out = withTarget(out, target);
538	    if (context.length) out = withSection(out, 'Context', context);
539	    if (result.delivered?.length) out = withSection(out, DELIVERED_HEADING, result.delivered, LEGACY_DELIVERED_HEADINGS);
540	    if (result.reason) out = withSection(out, 'Why the agent is here', [result.reason]);
541	    return out;
542	  });
543	  await setIssueBody(gh, repo, item.number, body);
544	
545	  await swapStatus(api, gh, repo, item, STATUS_RUNNING_EXECUTOR, AGENT);
546	  await api.comment(gh, repo, item.number,
547	    `${HANDOFF_MARKER}\nHanded off by executor \`${executorId}\` — invocation nonce \`${nonce}\`.`);
548	
549	  const invocation = await invokeAgent({ task, item, nonce, config });
550	  if (invocation.ok) {
551	    await api.comment(gh, repo, item.number,
552	      `Agent session started${invocation.sessionUrl ? `: ${invocation.sessionUrl}` : ''}.`);
553	    log(`- #${item.number} ${id}: handed off${invocation.sessionId ? ` (${invocation.sessionId})` : ''}`);
554	    return 'agent';
555	  }
556	  if (invocation.answered) {
557	    // The endpoint refused, so no session exists and none will: a token, a URL or
558	    // a routine is wrong, and every future pick would be refused the same way.
559	    await converge(api, gh, repo, item, STATUS_RUNNING_AGENT, NEEDS_HUMAN_ACTION, claim,
560	      `Could not start an agent session: ${invocation.error}\n\nNo session was started. Fix the invocation endpoint, then re-queue this item (${requeueHint}).`);
561	    return 'needs-human';
562	  }
563	  // NOTHING CAME BACK, and this is the case the whole design turns on: the call
564	  // may have started a session. Re-queueing here is what would put two sessions on
565	  // one item, and converging to triage would kill a run that is very possibly
566	  // alive. So the item STAYS with the agent and says the outcome is unknown —
567	  // whichever way it went is then settled by a rule that already exists: a session
568	  // that started converges the item, and one that never did leaves the item silent
569	  // until the janitor's agent leash sweeps it to triage.
570	  await api.comment(gh, repo, item.number,
571	    `The agent invocation got no answer: ${invocation.error}\n\n`
572	    + 'The session may or may not have started, so nothing here re-tries it — a second call could put two sessions on this item. '
573	    + 'If a session did start it will converge this item; if it did not, the janitor\'s agent leash parks it for a human within a few hours.');
574	  log(`! #${item.number} ${id}: invocation unanswered — left with the agent, leash decides — ${invocation.error}`);
575	  return 'unknown';
576	}
577	
578	// LETTING GO OF AN OPEN ITEM KILLS YOUR CLAIM (PRINCIPLES.md, F24). An executor
579	// that stops owning an item without closing it — the roll, and every
580	// `needs-human` park — strikes its own claim by appending the episode marker to
581	// it. `claimWinner` already treats the last marker as the boundary, so a struck
582	// claim stops outranking anything and the next claimant wins on its first try.
583	//
584	// APPENDING rather than commenting is what lets the roll stay silent (PRINCIPLES.md): an
585	// hourly task that declines every hour adds no timeline entry. A successful
586	// hand-off deliberately does NOT strike — the episode is still live, owned by the
587	// agent session — and neither does a close, since nothing re-claims a closed item.
588	//
589	// Struck BEFORE the label swap, so the crash window degrades the safe way: an
590	// executor that dies between the two leaves the item `task:executing` with a
591	// spent claim, which the scheduler run's leash reclaim already recovers. Striking after
592	// would leave exactly the state this fixes — parked, re-queued by a human, and
593	// unclaimable forever.
594	async function strikeClaim(api, gh, repo, claim) {
595	  if (!claim || (claim.body ?? '').includes(EPISODE_MARKER)) return;
596	  await api.editComment(gh, repo, claim.id,
597	    `${claim.body}\n\n${EPISODE_MARKER}\nThis claim is spent — the executor released this item without closing it.`);
598	}
599	
600	// Every exit converges the item exactly once, with one comment saying what
601	// happened — the terminal-state discipline the incidents bought. The claim sits
602	// before the body so every state argument is grouped ahead of the prose.
603	//
604	// THE COMMENT CARRIES THE EXECUTION RECORD (docs/PRINCIPLES.md). Actions logs

