1	// The tasks fold's FIRST source: what each run of the machinery cost.
2	//
3	// The run LISTINGS are not re-derived here — `readRuns` in the session fold's own
4	// task folder already reads exactly this source, two calls flat however many runs
5	// are in the window, and a second implementation of the same listing is a second
6	// thing to drift. What this module adds is the two reads that listing cannot make:
7	//
8	//   - THE JOBS LISTING, one call per run, because Actions bills per JOB and the run
9	//     listing carries no job timings at all. A run's billed minutes are the sum over
10	//     its jobs of each job's wall time rounded up to a whole minute.
11	//   - THE JOB LOG, for a SCHEDULER run only. A tick owns no work item, so the
12	//     `claudinite-run-cost` record it printed exists nowhere but its log. An
13	//     executor run's record rides the items it settled, which the item reader picks
14	//     up for free.
15	//
16	// THE BUDGET, stated here because it is the reason the module is shaped this way.
17	// Per fold: 2 run listings, flat; 1 jobs listing per run this fold is seeing for the
18	// first time; and, for at most `SCHEDULER_RUNS_PER_FOLD` scheduler runs, at most
19	// `JOB_LOGS_PER_RUN` log reads each. On this repo's cadence — the scheduler's two
20	// ticks a day and the executor runs a quiet queue dispatches — that is under ten
21	// calls a day, which `test/tasks/tasks-usage-fold/read-run-costs.test.mjs` asserts
22	// by counting the fetches a representative day makes.
23	//
24	// `MAX_RUN_READS` is the runaway guard rather than the budget: a day that somehow
25	// produced hundreds of runs stops at the cap, leaves the watermark at the last run
26	// fully read, and says so — the next fold continues from exactly there. Reading a
27	// repo's whole rate limit to measure it would be the fold costing more than the
28	// thing it measures.
29	//
30	// FAIL-SOFT per read, like every source in both folds: a jobs listing that cannot be
31	// read costs that run its minutes and nothing else, and a log that cannot be read
32	// costs that tick its cost record. Neither takes the run counts down with it.
33	
34	import { makeReader as makeJsonReader, readRuns, WATCHED_WORKFLOWS } from '../usage-fold/read-runs.mjs';
35	import { parseRunCosts } from '../../src/items/run-record.mjs';
36	
37	const API = process.env.GITHUB_API_URL || 'https://api.github.com';
38	
39	// At most this many scheduler runs have their log read in one fold — the two ticks
40	// a day the cron fires, plus one fold's slack for a late fire.
41	export const SCHEDULER_RUNS_PER_FOLD = 2;
42	
43	// Within one of those runs, at most this many job logs are read. A tick's record is
44	// printed by the run job, which the jobs listing returns first; the second read
45	// exists for a member whose workflow orders its jobs the other way. Skipped jobs are
46	// never read — they have no log.
47	export const JOB_LOGS_PER_RUN = 2;
48	
49	// The runaway guard on per-run reads in one fold. Not the budget — see the header.
50	export const MAX_RUN_READS = 40;
51	
52	// The reader this module needs: JSON like the session fold's, plus text for a log.
53	// `fetchImpl` is injected so the tests drive it without a network.
54	export function makeReader({ token = process.env.GITHUB_TOKEN, api = API, fetchImpl = fetch } = {}) {
55	  const headers = {
56	    accept: 'application/vnd.github+json',
57	    'x-github-api-version': '2022-11-28',
58	    'user-agent': 'claudinite-tasks-usage-fold',
59	    ...(token ? { authorization: `Bearer ${token}` } : {}),
60	  };
61	  const { json } = makeJsonReader({ token, api, fetchImpl });
62	  return {
63	    json,
64	    async text(path) {
65	      // The logs endpoint answers a redirect to a blob; `fetch` follows it, and a
66	      // run whose logs have aged out of retention answers 404 — which is an ANSWER,
67	      // not a failure: that tick's cost is simply unrecoverable now.
68	      const res = await fetchImpl(`${api}${path}`, { headers });
69	      if (res.status !== 200) return null;
70	      try { return await res.text(); } catch { return null; }
71	    },
72	  };
73	}
74	
75	// HOW A JOB'S MINUTES ARE COUNTED. Each job's wall time — `completed_at` minus
76	// `started_at` — rounded UP to a whole minute, summed over the run's jobs.
77	//
78	// THE ROUNDING RULE IS UNVERIFIED FROM HERE. #1872 asks for it to be checked against
79	// GitHub's billing documentation and cited; a session in this repo cannot reach
80	// `docs.github.com` at all (the egress proxy refuses the domain), so the rule below
81	// is the one this repo already states for itself in `src/execute/loop.mjs` —
82	// "Actions bills each job's runtime rounded UP to the next minute" — and not a
83	// reading of the docs. Confirming it against
84	// docs.github.com/en/billing/concepts/product-billing/github-actions needs an
85	// unblocked environment, and this function is the only place the rule is encoded.
86	//
87	// A job with no `completed_at` (still running, or killed without one) contributes
88	// NO minutes rather than zero, and the run's total is absent when no job could be
89	// measured at all — unknown is a state of its own here as everywhere else.
90	export function billedMinutes(jobs) {
91	  let minutes = null;
92	  for (const job of jobs ?? []) {
93	    const from = Date.parse(job?.started_at ?? '');
94	    const to = Date.parse(job?.completed_at ?? '');
95	    if (!Number.isFinite(from) || !Number.isFinite(to) || to < from) continue;
96	    minutes = (minutes ?? 0) + Math.ceil((to - from) / 60000);
97	  }
98	  return minutes;
99	}
100	
101	// One run's jobs, or null when the listing could not be read.
102	export async function readJobs(reader, repo, runId) {
103	  const json = await reader.json(`/repos/${repo}/actions/runs/${runId}/jobs?per_page=100`);
104	  return Array.isArray(json?.jobs) ? json.jobs : null;
105	}
106	
107	// A job that produced a log at all. A skipped job has none, and asking for one
108	// spends a call on a 404.
109	const ran = (job) => job?.conclusion !== 'skipped' && job?.conclusion != null;
110	
111	// The cost record a scheduler tick printed, out of its jobs' logs. Reads at most
