113	export async function readCostFromLog(reader, repo, jobs, { budget = JOB_LOGS_PER_RUN } = {}) {
114	  let reads = 0;
115	  for (const job of (jobs ?? []).filter(ran)) {
116	    if (reads >= budget) break;
117	    reads += 1;
118	    const text = await reader.text(`/repos/${repo}/actions/jobs/${job.id}/logs`);
119	    // The LAST record in the log, not the first: a tick prints its record once, at
