  // fell outside the window has no day to be counted in.
  const days = foldDays({
    runs: withItemCosts([], [item(1, TODAY, { costs: [cost('999', 25, { pick: 250 })] })]),
    items: [item(1, TODAY, { costs: [cost('999', 25, { pick: 250 })] })],
    today: TODAY,
  });
  assert.deepEqual(days[TODAY].runCosts, {});
