1	// The executor loop end to end against a fake GitHub — pick, claim, evaluate,
2	// code-work, hand off, converge. The pure rules are tested beside this; what this
3	// pins is that the SHELL actually drives them to a terminal state, which is the
4	// thing a fixture over the rules alone can never say.
5	
6	import { test } from 'node:test';
7	import assert from 'node:assert/strict';
8	import { runExecutor } from '../../src/execute/loop.mjs';
9	import { parseWorkItemBody } from '../../src/items/work-item.mjs';
10	import { normalizeTaskDeclaration } from '../../src/contract/task-contract.mjs';
11	import { startRunCost, parseRunCost, parseRunCosts } from '../../src/items/run-record.mjs';
12	
13	const SCHEDULE = { dailyHour: 4, weeklyDay: 'Sun', monthlyDay: 1 };
14	const CONFIG = { taskScheduler: SCHEDULE, packConfig: {} };
15	
16	// A fake repo: issues with labels, bodies, comments and state, driven through the
17	// same REST paths the shell calls.
18	function fakeRepo(issues = [], pulls = []) {
19	  const state = {
20	    issues: issues.map((i) => ({ comments: [], state: 'open', ...i })), commentSeq: 100, calls: [],
21	    pulls: pulls.map((p) => ({ comments: [], state: 'open', ...p })),
22	  };
23	  const find = (n) => state.issues.find((i) => i.number === n);
24	  const findPull = (n) => state.pulls.find((p) => p.number === n);
25	  const gh = async (path, { method = 'GET', body } = {}) => {
26	    state.calls.push(`${method} ${path}`);
27	    let m;
28	    if (method === 'GET' && /^\/repos\/[^/]+\/[^/]+\/pulls\?/.test(path)) {
29	      return { status: 200, json: state.pulls.filter((p) => p.state === 'open') };
30	    }
31	    if ((m = /^\/repos\/[^/]+\/[^/]+\/pulls\/(\d+)$/.exec(path))) {
32	      const pr = findPull(Number(m[1]));
33	      if (!pr) return { status: 404, json: null };
34	      if (method === 'PATCH') Object.assign(pr, body);
35	      return { status: 200, json: pr };
36	    }
37	    if (/\/git\/refs\/heads\//.test(path)) return { status: 204, json: null };
38	    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\/(\d+)\/comments/.exec(path)) && !find(Number(m[1])) && findPull(Number(m[1]))) {
39	      if (method === 'POST') findPull(Number(m[1])).comments.push({ body: body.body });
40	      return { status: 201, json: {} };
41	    }
42	    if (method === 'GET' && /^\/repos\/[^/]+\/[^/]+\/issues\?/.test(path)) {
43	      const page = Number(/[?&]page=(\d+)/.exec(path)?.[1] ?? 1); // NOT /page=/ — that matches per_page
44	      return { status: 200, json: page === 1 ? state.issues.filter((i) => i.state === 'open') : [] };
45	    }
46	    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\/comments\/(\d+)$/.exec(path))) {
47	      const id = Number(m[1]);
48	      for (const issue of state.issues) {
49	        const c = issue.comments.find((x) => x.id === id);
50	        if (c) { if (method === 'PATCH') c.body = body.body; return { status: 200, json: c }; }
51	      }
52	      return { status: 404, json: null };
53	    }
54	    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\/(\d+)\/comments/.exec(path))) {
55	      const issue = find(Number(m[1]));
56	      if (method === 'POST') {
57	        issue.comments.push({ id: (state.commentSeq += 1), body: body.body });
58	        issue.updated_at = 'now';
59	        return { status: 201, json: {} };
60	      }
61	      return { status: 200, json: issue.comments };
62	    }
63	    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\/(\d+)\/labels\/(.+)$/.exec(path))) {
64	      const issue = find(Number(m[1]));
65	      issue.labels = issue.labels.filter((l) => l !== decodeURIComponent(m[2]));
66	      return { status: 200, json: {} };
67	    }
68	    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\/(\d+)\/labels$/.exec(path))) {
69	      const issue = find(Number(m[1]));
70	      issue.labels.push(...body.labels);
71	      return { status: 200, json: {} };
72	    }
73	    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\/(\d+)$/.exec(path))) {
74	      const issue = find(Number(m[1]));
75	      if (method === 'PATCH') Object.assign(issue, body);
76	      return { status: 200, json: issue };
77	    }
78	    return { status: 404, json: null };
79	  };
80	  return { state, gh, find, findPull };
81	}
82	
83	const workItem = (number, task, labels, body = null) => ({
84	  number, title: `[claudinite-work] p/${task}`, labels,
85	  body: body ?? `packs/p/tasks/${task}/task.md\n\nExecute the Claudinite task above.\n`,
86	  created_at: '2026-08-14T04:00:00Z', updated_at: '2026-08-14T04:00:00Z',
87	});
88	
89	// `taskDir` is a REAL directory: the executor probes it before it runs anything,
90	// because a task can be deleted out from under an item this run already queued.
91	// `gate` is how a fixture states its verdict: the declarative expression is the
92	// only precondition mechanism, so a fixture that must decline (or throw) does it
93	// through a task-local term, exactly as a real task would.
94	const term = (holds) => new Map([['gate', { signals: [], holds }]]);
95	const RUNS = term(() => ({ holds: true }));
96	const task = (id, decl = {}, terms = RUNS) => ({
97	  pack: 'p', id, taskDir: process.cwd(), taskPath: `packs/p/tasks/${id}/task.md`,
98	  decl: normalizeTaskDeclaration({ id, frequency: 'daily', agent_model: 'sonnet', preconditions: ['gate'], expected_outcome: 'fresh_pr', ...decl }),
99	  terms,
100	});
101	
102	// `random` is pinned ascending so a fixture with several pickable items picks the
103	// FIRST one it lists — production's draw is random (PRINCIPLES.md) and a test that let it
104	// vary would be a coin flip, not a test.
105	const ascendingDraw = () => { let n = 0; return () => (n += 1) / 1000; };
106	
107	const drive = (repo, tasks, over = {}) => runExecutor({
108	  gh: repo.gh, repo: 'o/r', root: '/tmp', config: CONFIG, tasks,
109	  executorId: 'E1', now: () => new Date('2026-08-14T04:20:00Z'), random: ascendingDraw(),
110	  collectSignalsFor: async () => ({}),
111	  runTaskCodeWork: async () => ({ ok: true, agentRequested: false }),
112	  invokeAgent: async () => ({ ok: true, sessionId: 's-1' }),
113	  log: () => {},
114	  ...over,
115	});
116	
117	// --- the target (PRINCIPLES.md) ---------------------------------------------------
118	// The executor decides which branch and pull request the run works on ONCE, after
119	// the precondition's go and before code-work, and both phases are handed the
120	// answer: code-work as environment, the agent as item fields.
121	
122	test('code-work is handed the target the executor resolved, minted under the task\'s prefix', async () => {
123	  const repo = fakeRepo([workItem(1, 'a', ['task:status:waiting-for-executor'])]);
124	  const seen = [];
125	  await drive(repo, [task('a', { agent_model: 'none', code_work: 'node w.mjs', code_work_timeout: 60 })], {
126	    runTaskCodeWork: async (t, { target }) => { seen.push(target); return { ok: true, agentRequested: false }; },
127	  });
